pm.test('First request: status 200', () => {
  pm.response.to.have.status(200);
});

// Send the second, identical PUT from the test script
pm.sendRequest({
  url: pm.request.url.toString(),
  method: 'PUT',
  header: { 'Content-Type': 'application/json' },
  body: pm.request.body
}, (err, res) => {
  if (err) { throw new Error(`Second request failed: ${err}`); }

  pm.test('Second request: status 200', () => {
    pm.expect(res.code).to.eql(200);
  });

  const secondItem = res.json();

  pm.test('Data is identical after both requests', () => {
    pm.expect(secondItem.name).to.eql(firstItem.name);
    pm.expect(secondItem.state).to.eql(firstItem.state);
    pm.expect(secondItem.webLink).to.eql(firstItem.webLink);
  });

  pm.test('createdDate did not change', () => {
    pm.expect(secondItem.createdDate).to.eql(firstItem.createdDate);
  });
});

