const baseUrl = pm.environment.get('baseUrl');
const id = pm.collectionVariables.get('fixtureId');

const del = () => new Promise((resolve) => {
  pm.sendRequest({
    url: `${baseUrl}/wish-items/${id}`,
    method: 'DELETE'
  }, (err, res) => {
    if (err) { throw new Error(`Первое удаление не выполнено: ${err}`); }
    if (res.code !== 204) { throw new Error(`Первое удаление вернуло ${res.code}, ожидался 204`); }
    resolve();
  });
});

(async () => {
  await del();

  // объект удалён — убираем его из реестра
  const ids = JSON.parse(pm.collectionVariables.get('createdIds') || '[]');
  const left = ids.filter(x => String(x) !== String(id));
  pm.collectionVariables.set('createdIds', JSON.stringify(left));
})();

// WISH-DEL-003 — repeated delition 
// Expected (api cases table): 405, item is rejected
// Common check "No server error (5xx)" runs from the smoke folder script

pm.test('Status 404: wish item not found', () => {
  pm.response.to.have.status(404);
});

const cases = [
  { id: '0', expected: 404 },
  { id: '-1', expected: 404 },
  { id: 'abc', expected: 404 },
  { id: '^&', expected: 404 },
  { id: '999999', expected: 404 },
  { id: '99999999999999999999', expected: 404 }
];

cases.forEach(c => {
  pm.sendRequest({
    url: pm.variables.replaceIn('{{baseUrl}}') + '/wish-items/' + c.id,
    method: 'GET'
  }, (err, res) => {
    pm.test('id=' + c.id + ' -> expected ' + c.expected + ', got ' + res.code, () => {
      pm.expect(res.code).to.eql(c.expected);
    });
  });
});

